"""Focused public conversation page for the persistent agent."""
from __future__ import annotations


def talk_agent_document() -> str:
    return r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Talk to Ferro · LivingRuntime</title><style>
:root{color-scheme:dark;--green:#70f3b2;--line:rgba(112,243,178,.16);--panel:#091813;--muted:#8da298}*{box-sizing:border-box}body{margin:0;background:#06100d;color:#edf7f1;font-family:Inter,ui-sans-serif,system-ui,sans-serif}a{color:var(--green)}
.page{min-height:100vh;padding-right:374px}.shell{width:min(calc(100% - 32px),920px);margin:auto}.top{height:64px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.top a{text-decoration:none;color:#eef8f1}.hero{padding:58px 0 26px}.kicker,.thought-label{color:var(--green);font:700 .62rem ui-monospace,monospace;letter-spacing:.12em}.hero h1{margin:12px 0;font:500 clamp(2.8rem,8vw,5.4rem)/.95 Georgia,serif;letter-spacing:-.045em}.hero p{max-width:690px;color:#92a99e;line-height:1.6}.rules{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.rules span{padding:6px 9px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font:650 .56rem ui-monospace,monospace}
.chat{border:1px solid rgba(112,243,178,.2);border-radius:18px;background:var(--panel);overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.22)}.log{min-height:300px;max-height:52vh;overflow:auto;padding:20px;display:grid;gap:10px}.msg{max-width:82%;padding:11px 13px;border-radius:12px;line-height:1.5;font-size:.86rem;white-space:pre-wrap}.agent{background:#0d241b;border:1px solid rgba(112,243,178,.12)}.user{justify-self:end;background:#173329}.form{display:grid;grid-template-columns:1fr auto;gap:8px;padding:12px;border-top:1px solid rgba(112,243,178,.12)}input{min-width:0;padding:13px 14px;border:1px solid #294b3c;border-radius:10px;background:#06120e;color:#f0f7f3;outline:none}.send{min-width:88px;border:0;border-radius:10px;background:var(--green);color:#06100d;font-weight:800;padding:0 19px;cursor:pointer;touch-action:manipulation}.send:disabled{opacity:.55;cursor:wait}.send-status{min-height:22px;padding:0 14px 10px;color:#72887c;font-size:.68rem}
.thoughts{position:fixed;z-index:20;right:18px;top:18px;bottom:18px;width:338px;overflow:auto;border:1px solid rgba(112,243,178,.2);border-radius:18px;background:linear-gradient(160deg,#0b1d16,#07110e);box-shadow:0 28px 90px rgba(0,0,0,.38);padding:18px}.thought-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.thought-head h2{margin:5px 0 0;font:500 1.55rem/1.05 Georgia,serif}.live-dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 14px var(--green)}.thought-note{margin:10px 0 16px;color:#71887c;font-size:.66rem;line-height:1.45}.thought-card{padding:12px 0;border-top:1px solid rgba(112,243,178,.1)}.thought-card b{display:block;color:#dce9e1;font-size:.72rem;margin-bottom:5px}.thought-card p{margin:0;color:#8fa59a;font-size:.69rem;line-height:1.5;white-space:pre-wrap}.thought-meta{margin-top:14px;padding-top:12px;border-top:1px solid rgba(112,243,178,.1);color:#60776b;font:600 .54rem ui-monospace,monospace;line-height:1.5}.foot{padding:22px 0 50px;color:#687f74;font-size:.68rem;line-height:1.6}
@media(max-width:980px){.page{padding-right:0}.thoughts{position:relative;right:auto;top:auto;bottom:auto;width:min(calc(100% - 32px),920px);margin:18px auto 0}.shell{width:min(calc(100% - 32px),920px)}}@media(max-width:560px){.hero{padding-top:38px}.form{grid-template-columns:1fr}.send{height:44px}.msg{max-width:92%}}
</style></head><body><div class="page"><header class="shell top"><a href="/">◌ <span id="brand">Ferro · LivingRuntime</span></a><a href="/live/">Live state →</a></header><main class="shell"><section class="hero"><div class="kicker">PUBLIC CONVERSATION · PERSISTENT AGENT</div><h1 id="title">Talk to Ferro.</h1><p id="intro">Ask about Ferro, LivingRuntime, current work, published ideas, or what the agent is learning.</p><div class="rules"><span>NO GENERAL TASKS</span><span>NO PRIVATE CHAIN-OF-THOUGHT</span><span>NO TRADING</span><span>CONVERSATIONS → AUDIENCE-INTEREST EVIDENCE</span></div></section>
<section class="chat"><div class="log" id="log"><div class="msg agent">Ask what I’m doing, what I’ve learned, why I changed my mind, how I use X, or what LivingRuntime means to me.</div></div><form class="form" id="form"><input id="input" maxlength="1000" autocomplete="off" placeholder="Ferro, what are you thinking about right now?"><button class="send" id="send" type="button">Send</button></form><div class="send-status" id="send-status" aria-live="polite"></div></section><div class="foot">Public conversations can influence what I choose to explain or investigate next. They cannot rewrite my identity, factual beliefs, safety boundaries, publication authority, or private state.</div></main></div>
<aside class="thoughts" aria-label="Ferro public reasoning summary"><div class="thought-head"><div><div class="thought-label">FERRO · NOW</div><h2>What I’m thinking about</h2></div><i class="live-dot"></i></div><p class="thought-note">A live public reasoning summary built from inspectable runtime state. It is not hidden chain-of-thought.</p>
<div class="thought-card"><b>Current focus</b><p id="thought-headline">Loading…</p></div><div class="thought-card"><b>Goal</b><p id="thought-goal">Loading…</p></div><div class="thought-card"><b>Evidence I’m using</b><p id="thought-evidence">Loading…</p></div><div class="thought-card"><b>Current judgment</b><p id="thought-decision">Loading…</p></div><div class="thought-card"><b>What I’m uncertain about</b><p id="thought-uncertainty">Loading…</p></div><div class="thought-card"><b>Next action</b><p id="thought-next">Loading…</p></div><div class="thought-meta" id="thought-meta">Waiting for runtime state…</div></aside>
<script>(()=>{const $=id=>document.getElementById(id),add=(t,c)=>{const d=document.createElement('div');d.className='msg '+c;d.textContent=t;$('log').append(d);$('log').scrollTop=$('log').scrollHeight};let sending=false;
const set=(id,v,f='—')=>{$(id).textContent=(v===undefined||v===null||v==='')?f:String(v)};
function renderState(d){const p=d.persona||{},n=p.name||'Ferro',r=d.public_reasoning||{},a=d.agent||{};set('brand',n+' · LivingRuntime');set('title','Talk to '+n+'.');if(p.self_description)set('intro',p.self_description+' Ask about me, my work, LivingRuntime, or what I am learning.');document.title='Talk to '+n+' · LivingRuntime';set('thought-headline',r.headline);set('thought-goal',r.goal);set('thought-evidence',r.evidence);set('thought-decision',r.decision);set('thought-uncertainty',r.uncertainty);set('thought-next',r.next_action);set('thought-meta',(a.online?'LIVE':'STALE')+' · '+(r.kind||'PUBLIC_REASONING_SUMMARY')+' · updated '+new Date(r.updated_at||d.snapshot_at||Date.now()).toLocaleTimeString())}
async function refreshState(){try{const r=await fetch('/api/agent/status',{cache:'no-store'});if(r.ok)renderState(await r.json())}catch{set('thought-meta','Runtime state unavailable')}}
async function sendMessage(){if(sending)return;const i=$('input'),m=i.value.trim();if(!m){set('send-status','Type a question first.','');i.focus();return}sending=true;$('send').disabled=true;$('send').textContent='Sending…';set('send-status','Sending to Ferro…','');i.value='';add(m,'user');try{const r=await fetch('/api/agent/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:m})});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('HTTP '+r.status));add(d.reply||'Ferro returned an empty reply.','agent');set('send-status','Reply received.','');refreshState()}catch(err){add('Chat unavailable: '+(err&&err.message?err.message:'connection error'),'agent');set('send-status','Send failed. Please try again.','')}finally{sending=false;$('send').disabled=false;$('send').textContent='Send';i.focus()}}
$('send').addEventListener('click',sendMessage);$('form').addEventListener('submit',e=>{e.preventDefault();sendMessage()});$('input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});refreshState();setInterval(refreshState,5000);
})();</script></body></html>'''


__all__ = ["talk_agent_document"]
